    // Draw Parcel & Fit Bounds
    useEffect(() => {
        if (!mapInstanceRef.current || !parcel.boundary || !window.google) return;

        const polygon = new window.google.maps.Polygon({
            paths: parcel.boundary,
            strokeColor: '#f59e0b',
            strokeOpacity: 0.8,
            strokeWeight: 2,
            fillColor: '#fbbf24',
