                            onClick={() => window.location.reload()}
                            className="mt-3 text-xs text-emerald-600 font-medium hover:underline"
                        >
                            Retry
                        </button>
                    </div>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

