                        ) : (
                            <span className="text-gray-400 text-sm italic">N/A</span>
                        )}
                    </div>
                </div>
            </div>

            <div className="bg-gradient-to-br from-emerald-800 to-emerald-900 rounded-xl shadow-lg p-6 text-white">
                <h3 className="font-bold opacity-90 mb-1">Agronomist Note</h3>
                <p className="text-emerald-100 text-sm leading-relaxed">
                   {currentNdvi > 0.6 
                     ? `Vegetation index (NDVI: ${currentNdvi.toFixed(2)}) indicates vigorous growth. Biomass development is consistent with the planting date.`
                     : currentNdvi > 0 ? `Vegetation index is currently ${currentNdvi.toFixed(2)}. Monitor areas with yellow overlay for potential nutrient stress or waterlogging.`
                     : "No recent vegetation data available. Please ensure backend connection is active to receive analysis."
