            if (!window.Cesium) {
                setError("CesiumJS failed to load. Please check your internet connection.");
            }
        }, 10000); // 10 second timeout

        return () => {
            clearInterval(interval);
            clearTimeout(timeout);
        };
    }, []);

    // 2. Initialize Cesium Viewer
    useEffect(() => {
        if (!isCesiumReady || !cesiumContainer.current) return;

        // Prevention flag for React Strict Mode double-invocation & async race conditions
        let isMounted = true;
        let initializationStarted = false;

        const initCesium = async () => {
            // Prevent concurrent initializations within the same effect cycle if called strangely
            if (viewerRef.current || initializationStarted) return;
            initializationStarted = true;

            // Set Access Token
            window.Cesium.Ion.defaultAccessToken = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJqdGkiOiIxOTZhN2M5Mi0wMjE0LTQ4NzEtOWJiMC1mNmIzM2MxMDQ3YTYiLCJpZCI6MzY5MTU4LCJpYXQiOjE3NjU1NDE1NTR9.WbGORKlqdnNJOWekIdOZDul1E0bow0viBJR7bPtcsdM";

            try {
                // Initialize Terrain
                let terrain;
                try {
                     // Using async terrain provider in newer Cesium versions
                     terrain = await window.Cesium.Terrain.fromWorldTerrain();
                } catch (err) {
                     console.warn("Could not load world terrain, falling back to ellipsoid.", err);
                }

                if (!isMounted) return;

                // Double-check ref in case another effect instance finished first (Strict Mode protection)
                if (viewerRef.current) return;

                const viewer = new window.Cesium.Viewer(cesiumContainer.current, {
                    terrain: terrain,
                    animation: false,
                    timeline: false,
                    baseLayerPicker: true, 
                    geocoder: true, 
