                    fullscreenButton: false,
                    infoBox: false, 
                    selectionIndicator: true
                });

                // Enable depth testing against the terrain
                viewer.scene.globe.depthTestAgainstTerrain = true;

                viewerRef.current = viewer;
                setCesiumLoaded(true);
            } catch (e: any) {
                if (!isMounted) return;
                console.error("Failed to initialize Cesium:", e);
                setError(e.message || "Failed to initialize 3D Globe engine.");
            }
        };

        if (!viewerRef.current) {
            initCesium();
        }

        // Cleanup function
        return () => {
            isMounted = false;
            if (viewerRef.current && !viewerRef.current.isDestroyed()) {
                viewerRef.current.destroy();
                viewerRef.current = null;
            }
        };
    }, [isCesiumReady]);

    // Render Parcels on the Globe
    useEffect(() => {
        if (!viewerRef.current || !cesiumLoaded) return;

        const viewer = viewerRef.current;

        // Clear previous entities
        viewer.entities.removeAll();

        parcels.forEach(p => {
            if(p.boundary) {
                // Determine if it's a simple polygon or multipolygon structure
                // Currently context normalizes this somewhat, but let's be safe
                const rings = Array.isArray(p.boundary[0]) && Array.isArray((p.boundary[0] as any)) 
                    ? p.boundary 
                    : [p.boundary]; // Wrap simple polygon in array

                // @ts-ignore
                rings.forEach((ring: any[]) => {
                    if (!Array.isArray(ring)) return;

                    const positions: number[] = [];
                    ring.forEach(pt => {
                        positions.push(pt.lng);
                        positions.push(pt.lat);
                    });

                    viewer.entities.add({
                        name: p.name,
                        description: `
                            <div style="padding:10px;">
                                <h3>${p.name}</h3>
                                <p>Crop: ${p.crop}</p>
                                <p>Size: ${p.size} ha</p>
                            </div>
                        `,
                        polygon: {
                            hierarchy: window.Cesium.Cartesian3.fromDegreesArray(positions),
                            height: 0, 
                            material: window.Cesium.Color.fromCssColorString('#10b981').withAlpha(0.5),
                            outline: true,
                            outlineColor: window.Cesium.Color.fromCssColorString('#065f46'),
                            outlineWidth: 2,
                            // Use TERRAIN to drape over the standard Cesium terrain
                            classificationType: window.Cesium.ClassificationType.TERRAIN
                        },
                        // Label Position (Center of first point for simplicity, or calc centroid)
                        position: window.Cesium.Cartesian3.fromDegrees(ring[0].lng, ring[0].lat),
                        point: { pixelSize: 0 },
                        label: {
                            text: p.name,
                            font: '14px sans-serif',
                            fillColor: window.Cesium.Color.WHITE,
                            outlineColor: window.Cesium.Color.BLACK,
                            outlineWidth: 2,
                            style: window.Cesium.LabelStyle.FILL_AND_OUTLINE,
                            verticalOrigin: window.Cesium.VerticalOrigin.BOTTOM,
                            pixelOffset: new window.Cesium.Cartesian2(0, -10),
                            distanceDisplayCondition: new window.Cesium.DistanceDisplayCondition(0.0, 50000.0),
                            disableDepthTestDistance: Number.POSITIVE_INFINITY
                        }
                    });
                });
            }
        });

    }, [parcels, cesiumLoaded]);

    const flyToParcel = (parcel: Parcel) => {
        if (!viewerRef.current || !parcel.boundary) return;

        const points: any[] = [];
        // Handle multipolygon structure safety
        const rings = Array.isArray(parcel.boundary[0]) && Array.isArray((parcel.boundary[0] as any))
             ? parcel.boundary 
             : [parcel.boundary];

        // @ts-ignore
        rings.forEach(ring => {
            if(Array.isArray(ring)) {
                ring.forEach(pt => points.push(pt.lng, pt.lat))
            }
        });

        if (points.length === 0) return;

        const rectangle = window.Cesium.Rectangle.fromCartesianArray(
            window.Cesium.Cartesian3.fromDegreesArray(points)
        );

        viewerRef.current.camera.flyTo({
            destination: rectangle,
            orientation: {
                heading: window.Cesium.Math.toRadians(0.0),
                pitch: window.Cesium.Math.toRadians(-45.0),
                roll: 0.0
            },
            duration: 2
        });
    };

    return (
        <div className="h-full w-full relative rounded-xl overflow-hidden shadow-sm border border-gray-200 bg-gray-900">

           {/* Cesium Map Container */}
           <div ref={cesiumContainer} className="absolute inset-0 z-0" />

           {/* Loading Overlay */}
           {!cesiumLoaded && !error && (
               <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-gray-900 text-white">
                   <Loader2 size={48} className="animate-spin text-emerald-500 mb-4" />
                   <p className="font-medium text-gray-300">Initializing 3D Globe...</p>
               </div>
           )}

           {/* Error Overlay */}
           {error && (
               <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-gray-100 p-8 text-center">
                   <div className="bg-red-100 p-4 rounded-full mb-4">
                       <AlertTriangle size={32} className="text-red-600" />
                   </div>
                   <h3 className="text-xl font-bold text-gray-900 mb-2">3D Globe Unavailable</h3>
                   <p className="text-gray-500 max-w-md">{error}</p>
                   <button 
                     onClick={() => window.location.reload()}
                     className="mt-6 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors"
                   >
                     Reload Application
                   </button>
               </div>
           )}

           {/* Left Sidebar: Places (Only show if loaded) */}
           {cesiumLoaded && (
               <div className="absolute top-4 left-4 z-10 max-h-[calc(100%-2rem)] flex flex-col gap-4">

                   <div className="bg-white/90 backdrop-blur p-4 rounded-xl shadow-lg border border-gray-200 w-64">
                       <h3 className="text-sm font-bold text-gray-900 mb-3 flex items-center gap-2">
