// Custom elements declarations for TypeScript
declare global {
  namespace JSX {
    interface IntrinsicElements {
      'gmp-map-3d': any;
      'gmp-polygon-3d': any;
    }
  }
}

export const GlobePage: React.FC = () => {
    const mapContainerRef = useRef<HTMLDivElement>(null);
    const map3dRef = useRef<any>(null);
    const { parcels } = useParcels();
    const [isReady, setIsReady] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // 1. Wait for Google Maps 3D library to be available
    useEffect(() => {
        let attempts = 0;
        const checkLibrary = setInterval(() => {
            attempts++;
            // Check if google.maps.maps3d is available
            if (window.google && window.google.maps && (window.google.maps as any).maps3d) {
                setIsReady(true);
                clearInterval(checkLibrary);
            } else if (attempts > 50) { // 5 seconds timeout
                setError("Google Maps 3D library failed to load. Please verify your API key and internet connection.");
                clearInterval(checkLibrary);
            }
        }, 100);

        return () => clearInterval(checkLibrary);
    }, []);

    // 2. Initialize the 3D Map
    useEffect(() => {
        if (!isReady || !mapContainerRef.current || map3dRef.current) return;

        try {
            const map3dElement = document.createElement('gmp-map-3d');
            // Initial view: Denmark area
            (map3dElement as any).center = { lat: 56.2639, lng: 9.5018, altitude: 500000 };
            (map3dElement as any).tilt = 45;
            (map3dElement as any).heading = 0;

            mapContainerRef.current.appendChild(map3dElement);
            map3dRef.current = map3dElement;
        } catch (err: any) {
            console.error("3D Map Init Error:", err);
            setError("Failed to initialize the 3D Map component.");
        }
    }, [isReady]);

    // 3. Render Parcels as 3D Polygons
    useEffect(() => {
        if (!map3dRef.current || parcels.length === 0) return;

        const map3d = map3dRef.current;

        // Clear previous polygons (Google Maps 3D elements are DOM children)
        const existingPolygons = map3d.querySelectorAll('gmp-polygon-3d');
        existingPolygons.forEach((p: any) => p.remove());

        parcels.forEach(parcel => {
            if (!parcel.boundary) return;

            // Handle multi-ring or simple polygon
            const rings = Array.isArray(parcel.boundary[0]) && Array.isArray((parcel.boundary[0] as any)) 
                ? (parcel.boundary as any[]) 
                : [parcel.boundary];

            rings.forEach((ring: any[]) => {
                const polygon3d = document.createElement('gmp-polygon-3d');
                (polygon3d as any).altitudeMode = 'CLAMP_TO_GROUND';
                (polygon3d as any).fillColor = 'rgba(16, 185, 129, 0.4)'; // Emerald-500 with alpha
                (polygon3d as any).strokeColor = 'rgb(6, 95, 70)'; // Emerald-900
                (polygon3d as any).strokeWidth = 3;
                (polygon3d as any).extruded = false;

                // Format: [{lat: x, lng: y}, ...]
                const outerBoundary = ring.map(pt => ({ lat: pt.lat, lng: pt.lng }));
                (polygon3d as any).outerBoundary = outerBoundary;

                map3d.appendChild(polygon3d);
            });
        });

    }, [parcels, isReady]);

    const flyToParcel = (parcel: Parcel) => {
        if (!map3dRef.current || !parcel.boundary) return;

        // Extract coordinates to find a center
        const rings = Array.isArray(parcel.boundary[0]) && Array.isArray((parcel.boundary[0] as any))
             ? (parcel.boundary as any[])
             : [parcel.boundary];

        const firstPoint = rings[0][0];

        if (!firstPoint) return;

        // Smooth camera transition
        map3dRef.current.flyCameraTo({
            endCamera: {
                center: { lat: firstPoint.lat, lng: firstPoint.lng, altitude: 800 },
                tilt: 55,
                heading: 0
            },
            durationMillis: 2500
        });
    };

    return (
        <div className="h-full w-full relative rounded-xl overflow-hidden shadow-sm border border-gray-200 bg-gray-900">

           {/* Map 3D Container */}
           <div ref={mapContainerRef} className="absolute inset-0 z-0 bg-gray-900" />

           {/* Loading Overlay */}
           {!isReady && !error && (
               <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-gray-900 text-white">
                   <Loader2 size={48} className="animate-spin text-emerald-500 mb-4" />
                   <p className="font-medium text-gray-300">Loading Photorealistic 3D Earth...</p>
               </div>
           )}

           {/* Error Overlay */}
           {error && (
               <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-gray-100 p-8 text-center">
                   <div className="bg-red-100 p-4 rounded-full mb-4">
                       <AlertTriangle size={32} className="text-red-600" />
                   </div>
                   <h3 className="text-xl font-bold text-gray-900 mb-2">3D View Unavailable</h3>
                   <p className="text-gray-500 max-w-md">{error}</p>
                   <button 
                     onClick={() => window.location.reload()}
                     className="mt-6 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors"
                   >
                     Retry Initialization
                   </button>
               </div>
           )}

           {/* Left Sidebar: My Places */}
           {isReady && !error && (
               <div className="absolute top-4 left-4 z-10 max-h-[calc(100%-2rem)] flex flex-col gap-4">

                   <div className="bg-white/90 backdrop-blur p-4 rounded-xl shadow-lg border border-gray-200 w-64">
                       <h3 className="text-sm font-bold text-gray-900 mb-3 flex items-center gap-2">
                           <MapPin size={16} className="text-emerald-600"/> My Parcels
                       </h3>

                       {parcels.length === 0 ? (
                           <p className="text-xs text-gray-500 italic">No fields defined yet.</p>
                       ) : (
                           <div className="space-y-1 max-h-60 overflow-y-auto pr-1">
                               {parcels.map(p => (
                                   <button 
                                       key={p.id}
                                       onClick={() => flyToParcel(p)}
                                       className="w-full text-left px-3 py-2 text-xs font-medium text-gray-700 hover:bg-emerald-50 hover:text-emerald-700 rounded-lg transition-colors flex items-center justify-between group"
                                   >
                                       <span>{p.name}</span>
                                       <Locate size={12} className="opacity-0 group-hover:opacity-100 transition-opacity"/>
                                   </button>
                               ))}
                           </div>
                       )}
                   </div>

                   {/* Instructions */}
                   <div className="bg-black/60 backdrop-blur-md p-3 rounded-xl text-white text-xs shadow-lg border border-white/10 w-64">
                       <h4 className="font-bold mb-2 flex items-center gap-2 text-emerald-400">
                           <MousePointer2 size={14} /> 3D Navigation
                       </h4>
                       <ul className="space-y-1.5 opacity-90">
                           <li className="flex items-center gap-2">
                               <span className="bg-white/20 px-1.5 rounded text-[10px]">Drag</span>
                               <span>Pan Camera</span>
                           </li>
                           <li className="flex items-center gap-2">
                               <span className="bg-white/20 px-1.5 rounded text-[10px]">Ctrl + Drag</span>
                               <span>Rotate / Tilt</span>
                           </li>
                           <li className="flex items-center gap-2">
                               <span className="bg-white/20 px-1.5 rounded text-[10px]">Scroll</span>
                               <span>Zoom In/Out</span>
                           </li>
                       </ul>
                   </div>

                    {/* Attribution/Info Tag */}
                    <div className="bg-white/90 backdrop-blur-sm px-3 py-1.5 rounded-full border border-gray-200 flex items-center gap-2 w-fit">
                        <Info size={12} className="text-blue-500" />
                        <span className="text-[10px] font-medium text-gray-600">Powered by Google Photorealistic 3D Tiles</span>
                    </div>
               </div>
           )}
        </div>
    );
};

