/**
 * Interactive 3D Globe Implementation
 * No Cesium Ion Access Token Required
 */

let viewer = null;
const tabElement = document.getElementById('tab-3d-earth');
const loader = document.getElementById('globe-loader');
const popup = document.getElementById('coord-popup');

// Initial View Parameters
const HOME_VIEW = {
    destination: Cesium.Cartesian3.fromDegrees(0.0, 0.0, 20000000.0),
    orientation: {
        heading: Cesium.Math.toRadians(0.0),
        pitch: Cesium.Math.toRadians(-90.0),
        roll: 0.0
    }
};

/**
 * Initializes the Cesium Viewer
 */
function initGlobe() {
    if (viewer) return;

    // 1. Check WebGL support
    if (!Cesium.FeatureDetection.supportsWebgl(Cesium.Context)) {
        document.getElementById('webgl-fallback').classList.remove('hidden');
        loader.classList.add('hidden');
        return;
    }

    // 2. Explicitly DISABLE Ion to avoid usage errors
    Cesium.Ion.defaultAccessToken = null;

    // 3. Initialize Viewer with OpenStreetMap imagery
    viewer = new Cesium.Viewer('cesiumContainer', {
        // Use free OpenStreetMap tiles
        imageryProvider: new Cesium.OpenStreetMapImageryProvider({
            url: 'https://a.tile.openstreetmap.org/'
        }),
        // Performance options: Disable unnecessary widgets
        animation: false,
        timeline: false,
        baseLayerPicker: false,
        geocoder: false,
        homeButton: false,
        infoBox: false,
        navigationHelpButton: false,
        sceneModePicker: false,
        selectionIndicator: false,
        requestRenderMode: true, // Only render when something changes (saves CPU)
        maximumRenderTimeChange: Infinity
    });

    // 4. Set Home View
    viewer.camera.setView(HOME_VIEW);

    // 5. Interaction: Click to show coordinates
    const handler = new Cesium.ScreenSpaceEventHandler(viewer.scene.canvas);
    handler.setInputAction((movement) => {
        const cartesian = viewer.camera.pickEllipsoid(movement.position, viewer.scene.globe.ellipsoid);
        if (cartesian) {
            const cartographic = Cesium.Cartographic.fromCartesian(cartesian);
            const lon = Cesium.Math.toDegrees(cartographic.longitude).toFixed(4);
            const lat = Cesium.Math.toDegrees(cartographic.latitude).toFixed(4);
            const alt = viewer.camera.positionCartographic.height.toFixed(0);

            popup.textContent = `LAT: ${lat}° | LON: ${lon}° | CAM ALT: ${alt}m`;
            popup.classList.remove('hidden');

            // Auto-hide popup after 3s
            setTimeout(() => popup.classList.add('hidden'), 3000);
        }
    }, Cesium.ScreenSpaceEventType.LEFT_CLICK);

    // 6. Hide loader once first frame is ready
    viewer.scene.postRender.addEventListener(function onFirstFrame() {
        loader.classList.add('hidden');
        viewer.scene.postRender.removeEventListener(onFirstFrame);
    });

    console.log("3D Globe Initialized");
}

/**
 * Cleanup/Stop Loop
 */
function stopGlobe() {
    if (viewer) {
        viewer.useDefaultRenderLoop = false;
        console.log("3D Globe Paused (Render loop stopped)");
    }
}

/**
 * Resume Loop
 */
function resumeGlobe() {
    if (viewer) {
        viewer.useDefaultRenderLoop = true;
        viewer.render();
        console.log("3D Globe Resumed");
    }
}

/**
 * Visibility Handler (Lazy Loading & Performance)
 */
const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            if (!viewer) {
                initGlobe();
            } else {
                resumeGlobe();
            }
        } else {
            stopGlobe();
        }
    });
}, { threshold: 0.1 });

// Start observing the tab
observer.observe(tabElement);

// Reset Button Logic
document.getElementById('reset-view').addEventListener('click', () => {
    if (viewer) {
        viewer.camera.flyTo({
            ...HOME_VIEW,
            duration: 1.5
        });
    }
});

import React, { useEffect, useRef, useState } from 'react';
import { useParcels } from '../context/ParcelContext';
import { Loader2, Globe, MapPin, MousePointer2, RefreshCw, AlertCircle } from 'lucide-react';

declare global {
