      roll: 0.0
    }
  };

  useEffect(() => {
    if (!containerRef.current || viewerRef.current) return;

    const initCesium = () => {
      try {
        if (!window.Cesium) {
          throw new Error("Cesium library not found. Check internet connection.");
        }

        // Disable Cesium ion to avoid token errors
        window.Cesium.Ion.defaultAccessToken = null;

        const viewer = new window.Cesium.Viewer(containerRef.current!, {
          // Use Free OpenStreetMap Imagery
          imageryProvider: new window.Cesium.OpenStreetMapImageryProvider({
            url: 'https://a.tile.openstreetmap.org/'
          }),
          // Performance Optimization
          animation: false,
          timeline: false,
          baseLayerPicker: false,
          geocoder: false,
          homeButton: false,
          infoBox: false,
          navigationHelpButton: false,
          sceneModePicker: false,
          selectionIndicator: false,
          requestRenderMode: true, // Only render on camera move (saves battery/CPU)
          maximumRenderTimeChange: Infinity
        });

        // Set View to Denmark
        viewer.camera.setView(HOME_VIEW);

        // Click Handler for Coordinates
        const handler = new window.Cesium.ScreenSpaceEventHandler(viewer.scene.canvas);
        handler.setInputAction((movement: any) => {
          const cartesian = viewer.camera.pickEllipsoid(movement.position, viewer.scene.globe.ellipsoid);
          if (cartesian) {
            const cartographic = window.Cesium.Cartographic.fromCartesian(cartesian);
            const lon = window.Cesium.Math.toDegrees(cartographic.longitude).toFixed(4);
            const lat = window.Cesium.Math.toDegrees(cartographic.latitude).toFixed(4);
            const alt = viewer.camera.positionCartographic.height.toFixed(0);

            setCoords(`Lat: ${lat}° | Lon: ${lon}° | Alt: ${alt}m`);
            // Auto-hide after delay
            setTimeout(() => setCoords(null), 4000);
          }
        }, window.Cesium.ScreenSpaceEventType.LEFT_CLICK);

        // Hide loader when first frame renders
        viewer.scene.postRender.addEventListener(function onFirstFrame() {
          setLoading(false);
          viewer.scene.postRender.removeEventListener(onFirstFrame);
        });

        viewerRef.current = viewer;
      } catch (err: any) {
        console.error(err);
        setError(err.message || "Failed to load 3D engine");
        setLoading(false);
      }
    };

    // Tiny delay to ensure DOM is ready
    const timer = setTimeout(initCesium, 100);
    return () => {
      clearTimeout(timer);
      if (viewerRef.current) {
        viewerRef.current.destroy();
        viewerRef.current = null;
      }
    };
  }, []);

  const handleReset = () => {
