/* Cesium 3D Globe Styling */
#cesiumContainer {
    width: 100%;
    height: 100%;
    margin: 0;
    padding: 0;
}

/* Ensure Cesium widgets respect our container boundaries */
.cesium-viewer {
    border-radius: inherit;
    overflow: hidden;
}

/* Coordinate Popup Animation */
@keyframes slideUp {
    from { transform: translate(-50%, 20px); opacity: 0; }
    to { transform: translate(-50%, 0); opacity: 1; }
}

.animate-in {
    animation: slideUp 0.3s ease-out forwards;
}

/* Standard scrollbar for the dashboard */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: #f1f1f1;
}

::-webkit-scrollbar-thumb {
  background: #d1d5db;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #9ca3af;
}

