    const cesiumContainer = useRef<HTMLDivElement>(null);
    const viewerRef = useRef<any>(null);
    const { parcels } = useParcels();
    const [cesiumLoaded, setCesiumLoaded] = useState(false);
    const [isCesiumReady, setIsCesiumReady] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Initial View (Denmark Center with 3D Tilt)
    const HOME_VIEW = {
        destination: null, // Set in useEffect
        orientation: {
            heading: 0.0,
            pitch: -0.6, // Tilted view to show 3D buildings/terrain (~ -35 degrees)
            roll: 0.0
        }
    };

    // 1. Poll for Cesium Script Load
    useEffect(() => {
        if (window.Cesium) {
            setIsCesiumReady(true);
            return;
        }

        const interval = setInterval(() => {
            if (window.Cesium) {
                setIsCesiumReady(true);
                clearInterval(interval);
            }
        }, 100);

        const timeout = setTimeout(() => {
            clearInterval(interval);
            if (!window.Cesium) {
                setError("CesiumJS failed to load. Please check your internet connection.");
            }
        }, 10000);

        return () => {
            clearInterval(interval);
            clearTimeout(timeout);
        };
    }, []);

    // 2. Initialize Cesium Viewer
    useEffect(() => {
        if (!isCesiumReady || !cesiumContainer.current) return;

        let isMounted = true;
        let initializationStarted = false;

        const initCesium = async () => {
            if (viewerRef.current || initializationStarted) return;
            initializationStarted = true;

            // Use the provided Ion Token
            window.Cesium.Ion.defaultAccessToken = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJqdGkiOiIxOTZhN2M5Mi0wMjE0LTQ4NzEtOWJiMC1mNmIzM2MxMDQ3YTYiLCJpZCI6MzY5MTU4LCJpYXQiOjE3NjU1NDE1NTR9.WbGORKlqdnNJOWekIdOZDul1E0bow0viBJR7bPtcsdM";

            try {
                // Initialize World Terrain
                const terrainProvider = await window.Cesium.createWorldTerrainAsync();

                if (!isMounted) return;

                const viewer = new window.Cesium.Viewer(cesiumContainer.current, {
                    terrainProvider: terrainProvider,
                    animation: false,
                    timeline: false,
                    baseLayerPicker: true, 
                    geocoder: true, 
                    homeButton: true,
                    sceneModePicker: true,
                    navigationHelpButton: false,
                    fullscreenButton: false,
                    infoBox: false, 
                    selectionIndicator: true,
                    msaaSamples: 4 // Better anti-aliasing for buildings
                });

                // Add 3D Buildings
                const buildingsTileset = await window.Cesium.createOsmBuildingsAsync();
                viewer.scene.primitives.add(buildingsTileset);

                // Enable depth testing against the terrain
                viewer.scene.globe.depthTestAgainstTerrain = true;

                // Initial Camera Setup
                viewer.camera.setView({
                    destination: window.Cesium.Cartesian3.fromDegrees(9.5018, 56.2639, 2000.0), // Zoomed in to see buildings
                    orientation: HOME_VIEW.orientation
                });

                viewerRef.current = viewer;
                setCesiumLoaded(true);
            } catch (e: any) {
                if (!isMounted) return;
                console.error("Failed to initialize Cesium:", e);
                setError(e.message || "Failed to initialize 3D Globe engine.");
            }
        };

        initCesium();

        return () => {
            isMounted = false;
            if (viewerRef.current && !viewerRef.current.isDestroyed()) {
                viewerRef.current.destroy();
                viewerRef.current = null;
            }
        };
    }, [isCesiumReady]);

    // 3. Render Parcels on the Globe
    useEffect(() => {
        if (!viewerRef.current || !cesiumLoaded) return;

        const viewer = viewerRef.current;
        viewer.entities.removeAll();

        parcels.forEach(p => {
            if(p.boundary) {
                const rings = Array.isArray(p.boundary[0]) && Array.isArray((p.boundary[0] as any)) 
                    ? p.boundary 
                    : [p.boundary];

                rings.forEach((ring: any[]) => {
                    if (!Array.isArray(ring)) return;

                    const positions: number[] = [];
                    ring.forEach(pt => {
                        positions.push(pt.lng);
                        positions.push(pt.lat);
                    });

                    viewer.entities.add({
                        name: p.name,
                        polygon: {
                            hierarchy: window.Cesium.Cartesian3.fromDegreesArray(positions),
                            material: window.Cesium.Color.fromCssColorString('#10b981').withAlpha(0.4),
                            outline: true,
                            outlineColor: window.Cesium.Color.fromCssColorString('#065f46'),
                            outlineWidth: 2,
                            classificationType: window.Cesium.ClassificationType.TERRAIN
                        },
                        position: window.Cesium.Cartesian3.fromDegrees(ring[0].lng, ring[0].lat),
                        label: {
                            text: p.name,
