                            fillColor: window.Cesium.Color.WHITE,
                            outlineColor: window.Cesium.Color.BLACK,
                            outlineWidth: 2,
                            style: window.Cesium.LabelStyle.FILL_AND_OUTLINE,
                            verticalOrigin: window.Cesium.VerticalOrigin.BOTTOM,
                            pixelOffset: new window.Cesium.Cartesian2(0, -15),
                            heightReference: window.Cesium.HeightReference.CLAMP_TO_GROUND,
                            disableDepthTestDistance: 1000000 // Ensure label is visible
                        }
                    });
                });
            }
        });
    }, [parcels, cesiumLoaded]);

    const flyToParcel = (parcel: Parcel) => {
        if (!viewerRef.current || !parcel.boundary) return;

        const points: number[] = [];
        const rings = Array.isArray(parcel.boundary[0]) && Array.isArray((parcel.boundary[0] as any))
             ? parcel.boundary 
             : [parcel.boundary];

        rings.forEach(ring => {
            if(Array.isArray(ring)) {
                ring.forEach(pt => points.push(pt.lng, pt.lat))
            }
        });

        if (points.length === 0) return;

        const rectangle = window.Cesium.Rectangle.fromCartesianArray(
            window.Cesium.Cartesian3.fromDegreesArray(points)
        );

        viewerRef.current.camera.flyTo({
            destination: rectangle,
            orientation: HOME_VIEW.orientation,
            duration: 2
        });
    };

    return (
        <div className="h-full w-full relative rounded-xl overflow-hidden shadow-sm border border-gray-200 bg-gray-900">
           <div ref={cesiumContainer} className="absolute inset-0 z-0" />

           {!cesiumLoaded && !error && (
               <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-gray-900 text-white">
                   <Loader2 size={48} className="animate-spin text-emerald-500 mb-4" />
                   <p className="font-medium text-gray-300">Loading 3D Terrain & Buildings...</p>
               </div>
           )}

           {error && (
               <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-gray-100 p-8 text-center">
                   <AlertTriangle size={48} className="text-red-600 mb-4" />
                   <h3 className="text-xl font-bold text-gray-900 mb-2">3D Globe Unavailable</h3>
                   <p className="text-gray-500 max-w-md">{error}</p>
                   <button 
                     onClick={() => window.location.reload()}
                     className="mt-6 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700"
                   >
                     Reload Application
                   </button>
               </div>
           )}

           {cesiumLoaded && (
               <div className="absolute top-4 left-4 z-10 max-h-[calc(100%-2rem)] flex flex-col gap-4">
                   <div className="bg-white/90 backdrop-blur p-4 rounded-xl shadow-lg border border-gray-200 w-64">
                       <h3 className="text-sm font-bold text-gray-900 mb-3 flex items-center gap-2">
                           <MapPin size={16} className="text-emerald-600"/> My Parcels
                       </h3>

                       {parcels.length === 0 ? (
