                     Reload Application
                   </button>
               </div>
           )}

           {cesiumLoaded && (
               <>
                   {/* Left Panel: Unified GIS Sidebar (Wider) */}
                   <div className="absolute top-4 left-4 z-10 max-h-[calc(100%-8rem)] flex flex-col gap-4 overflow-y-auto no-scrollbar pb-4">

                       {/* My Holdings Box */}
