app.post('/api/get-soil', async (req, res) => {
  try {
    const { polygon } = req.body;
    validatePolygon(polygon);

    const cacheKey = `soil:v1:${Buffer.from(JSON.stringify(polygon)).toString('base64')}`;
    const cached = await cacheGet(cacheKey);
    if (cached) return res.json(cached);

    const region = ee.Geometry(polygon);

    // SoilGrids 250m v2.0 Dataset paths (Community or Official)
    // We'll use the official ISRIC collection structure
    const layers = {
      clay: 'projects/soilgrids-isric/clay_mean',
      sand: 'projects/soilgrids-isric/sand_mean',
      silt: 'projects/soilgrids-isric/silt_mean',
      ph: 'projects/soilgrids-isric/phh2o_mean',
      soc: 'projects/soilgrids-isric/soc_mean',
      bd: 'projects/soilgrids-isric/bdod_mean'
    };

    // Aggregate 0-30cm (topsoil) for each property
    const getTopsoilMean = (path) => {
      const img = ee.Image(path);
      // Average the 0-5, 5-15, and 15-30cm bands
      return img.select(['clay_0-5cm_mean', 'clay_5-15cm_mean', 'clay_15-30cm_mean'])
               .reduce(ee.Reducer.mean());
    };

    // Create a multi-band image of topsoil properties
    const topsoil = ee.Image.cat([
      ee.Image('projects/soilgrids-isric/clay_mean').select(['clay_0-5cm_mean', 'clay_5-15cm_mean', 'clay_15-30cm_mean']).reduce(ee.Reducer.mean()).rename('clay'),
      ee.Image('projects/soilgrids-isric/sand_mean').select(['sand_0-5cm_mean', 'sand_5-15cm_mean', 'sand_15-30cm_mean']).reduce(ee.Reducer.mean()).rename('sand'),
      ee.Image('projects/soilgrids-isric/silt_mean').select(['silt_0-5cm_mean', 'silt_5-15cm_mean', 'silt_15-30cm_mean']).reduce(ee.Reducer.mean()).rename('silt'),
      ee.Image('projects/soilgrids-isric/phh2o_mean').select(['phh2o_0-5cm_mean', 'phh2o_5-15cm_mean', 'phh2o_15-30cm_mean']).reduce(ee.Reducer.mean()).rename('ph'),
      ee.Image('projects/soilgrids-isric/soc_mean').select(['soc_0-5cm_mean', 'soc_5-15cm_mean', 'soc_15-30cm_mean']).reduce(ee.Reducer.mean()).rename('soc'),
      ee.Image('projects/soilgrids-isric/bdod_mean').select(['bdod_0-5cm_mean', 'bdod_5-15cm_mean', 'bdod_15-30cm_mean']).reduce(ee.Reducer.mean()).rename('bd')
    ]);

    const stats = topsoil.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 250,
      maxPixels: 1e9,
      bestEffort: true
    });

    stats.evaluate(async (data, err) => {
      if (err) return res.status(500).json({ error: err });

      // Units Normalization
      // Clay/Sand/Silt: g/kg -> % (divide by 10)
      // pH: pH*10 -> pH (divide by 10)
      // SOC: dg/kg -> % (divide by 100)
      // BD: cg/cm3 -> g/cm3 (divide by 100)

      const result = {
        texture: {
          clay: data.clay ? Number((data.clay / 10).toFixed(1)) : null,
          sand: data.sand ? Number((data.sand / 10).toFixed(1)) : null,
          silt: data.silt ? Number((data.silt / 10).toFixed(1)) : null,
        },
        chemistry: {
          ph: data.ph ? Number((data.ph / 10).toFixed(1)) : null,
        },
        organic: {
          soc: data.soc ? Number((data.soc / 100).toFixed(2)) : null,
          som: data.soc ? Number((data.soc / 100 * 1.72).toFixed(2)) : null
        },
        physical: {
          bulkDensity: data.bd ? Number((data.bd / 100).toFixed(2)) : null
        }
      };

      await cacheSet(cacheKey, result);
      res.json(result);
    });

  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/get-layer', async (req, res) => {
  try {
    const { polygon, layer = 'ndvi' } = req.body;
    validatePolygon(polygon);
    const region = ee.Geometry(polygon);
    const end = ee.Date(Date.now());
    const start = end.advance(-90, 'day');

    const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(start, end)
        .map((img) => img.divide(10000).addBands(img.normalizedDifference(['B8', 'B4']).rename('NDVI')));

    let mapImage = s2.qualityMosaic('NDVI').clip(region).select('NDVI');
    let palette = ['#a1662f', '#eab308', '#84cc16', '#22c55e', '#14532d'];

    if(layer === 'ndmi') {
        mapImage = s2.qualityMosaic('NDVI').clip(region).normalizedDifference(['B8', 'B11']).rename('NDMI');
        palette = ['#caf0f8', '#0077b6', '#03045e'];
    }

    const stats = mapImage.reduceRegion({
        reducer: ee.Reducer.percentile([2, 98]),
        geometry: region,
        scale: 10,
        bestEffort: true
    });

    const bandName = mapImage.bandNames().get(0);
    const visualized = mapImage.visualize({
        min: stats.get(ee.String(bandName).cat('_p2')),
        max: stats.get(ee.String(bandName).cat('_p98')),
        palette: palette
    });

    visualized.getMap({}, (mapid) => {
        res.json({ tile_url: mapid.urlFormat });
    });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

