import { getBackendUrl } from './geeService';

export interface SoilData {
  texture: {
    sand: number | null; 
    silt: number | null; 
    clay: number | null; 
    label: string; 
  };
  chemistry: {
    ph: number | null;
    cec: number | null; 
    nitrogen: number | null; 
  };
  organic: {
    soc: number | null; 
    som: number | null; 
  };
  physical: {
    bulkDensity: number | null; 
  };
}

const getTextureClass = (sand: number | null, silt: number | null, clay: number | null): string => {
  if (sand === null || silt === null || clay === null) return 'N/A';
  if (clay >= 40) {
    if (sand > 45) return 'Sandy Clay';
    if (silt > 40) return 'Silty Clay';
    return 'Clay';
  }
  if (clay >= 27) {
    if (sand > 45) return 'Sandy Clay Loam';
    if (silt > 28) return 'Silty Clay Loam';
    return 'Clay Loam';
  }
  if (clay >= 12) {
    if (sand > 52) return 'Sandy Loam';
    if (silt > 50) return 'Silty Loam';
    return 'Loam';
  }
  if (silt > 80) return 'Silt';
  if (sand > 85) return 'Sand';
  if (sand > 70) return 'Loamy Sand';
  return 'Sandy Loam'; 
};

// Converters for GEE output to SoilData interface
const formatPolygonForBackend = (boundary: any) => {
    // Shared logic with geeService
    if (Array.isArray(boundary) && boundary.length > 0 && 'lat' in boundary[0]) {
        const arr = boundary.map(p => [p.lng, p.lat]);
        if (arr.length > 0) {
            const first = arr[0];
            const last = arr[arr.length - 1];
            if (first[0] !== last[0] || first[1] !== last[1]) arr.push(first);
        }
        return { type: "Polygon", coordinates: [arr] };
    }
    return boundary; // Assume already formatted or multi
};

export const fetchSoilData = async (lat: number, lng: number, boundary?: any): Promise<SoilData | null> => {
  const isOffline = localStorage.getItem('gee_simulation_mode') === 'true';
  if (isOffline || !boundary) return null;

  try {
    const backendUrl = getBackendUrl();
    const formattedBoundary = formatPolygonForBackend(boundary);

    const response = await fetch(`${backendUrl}/api/get-soil`, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
        'ngrok-skip-browser-warning': 'true'
      },
      body: JSON.stringify({ polygon: formattedBoundary })
    });

    if (!response.ok) throw new Error('Backend soil fetch failed');

    const data = await response.json();

    // Add texture label based on returned sand/silt/clay
    if (data.texture) {
        data.texture.label = getTextureClass(data.texture.sand, data.texture.silt, data.texture.clay);
    }

    return data as SoilData;
  } catch (error) {
    console.warn("GEE Soil Fetch Failed:", error);
    return null;
  }
};

