const FieldMonitorMap: React.FC<FieldMonitorMapProps> = ({ parcel, isOffline }) => {
    const mapRef = useRef<HTMLDivElement>(null);
    const mapInstanceRef = useRef<any>(null);
    const overlayRef = useRef<any>(null);

    const [activeLayer, setActiveLayer] = useState<'ndvi' | 'ndre' | 'ndmi' | 'lai' | 'lst'>('ndvi');
    const [loadingLayer, setLoadingLayer] = useState(false);

    useEffect(() => {
        if (!mapRef.current || !window.google || mapInstanceRef.current) return;
        const center = { lat: 56.2639, lng: 9.5018 };
        const map = new window.google.maps.Map(mapRef.current, {
            center,
            zoom: 13,
            mapTypeId: 'hybrid',
            disableDefaultUI: true,
            zoomControl: true,
        });
        mapInstanceRef.current = map;
    }, []);

    useEffect(() => {
        if (!mapInstanceRef.current || !parcel.boundary || !window.google) return;
        const polygon = new window.google.maps.Polygon({
            paths: parcel.boundary,
            strokeColor: '#f59e0b',
            strokeOpacity: 0.8,
            strokeWeight: 2,
            fillColor: '#fbbf24',
            fillOpacity: 0.0,
        });
        polygon.setMap(mapInstanceRef.current);
        const bounds = new window.google.maps.LatLngBounds();
        if (Array.isArray(parcel.boundary)) {
            const isMulti = Array.isArray(parcel.boundary[0]);
            if (isMulti) {
                (parcel.boundary as any[]).forEach(ring => ring.forEach((p: any) => bounds.extend(p)));
            } else {
                 (parcel.boundary as any[]).forEach((p: any) => bounds.extend(p));
            }
        }
        mapInstanceRef.current.fitBounds(bounds);
        return () => polygon.setMap(null);
    }, [parcel]);

    useEffect(() => {
        if (!mapInstanceRef.current || isOffline || !parcel.boundary) return;
        const loadLayer = async () => {
            setLoadingLayer(true);
            try {
                if (overlayRef.current) {
                    mapInstanceRef.current.overlayMapTypes.removeAt(0);
                    overlayRef.current = null;
                }
                const backendUrl = getBackendUrl();
                const result = await fetchGeeLayer(activeLayer, parcel.boundary, backendUrl);
                const tileUrl = result?.tile_url || (result as any);
                if (tileUrl && typeof tileUrl === 'string') {
                    const mapType = new window.google.maps.ImageMapType({
                        getTileUrl: (coord: any, zoom: any) => tileUrl.replace('{x}', coord.x.toString()).replace('{y}', coord.y.toString()).replace('{z}', zoom.toString()),
                        tileSize: new window.google.maps.Size(256, 256),
                        opacity: 0.85,
                    });
                    mapInstanceRef.current.overlayMapTypes.push(mapType);
                    overlayRef.current = mapType;
                }
            } catch (e) { console.error(e); } finally { setLoadingLayer(false); }
        };
        loadLayer();
    }, [activeLayer, isOffline, parcel]);

    const layers = [{ id: 'ndvi', label: 'NDVI' }, { id: 'ndre', label: 'NDRE' }, { id: 'ndmi', label: 'NDMI' }, { id: 'lai', label: 'LAI' }, { id: 'lst', label: 'LST' }];

    return (
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
            <div className="p-3 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <h3 className="font-bold text-gray-700 flex items-center gap-2"><Layers size={16} /> Field Map</h3>
                <div className="flex bg-white border border-gray-200 rounded-lg p-0.5">
                    {layers.map(layer => (
                        <button key={layer.id} onClick={() => setActiveLayer(layer.id as any)} disabled={isOffline}
                            className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${activeLayer === layer.id ? 'bg-emerald-100 text-emerald-800' : 'text-gray-600 hover:bg-gray-50'}`}>
                            {layer.label}
                        </button>
                    ))}
                </div>
            </div>
            <div className="relative h-[350px] w-full bg-gray-100">
                <div ref={mapRef} className="absolute inset-0 w-full h-full" />
                {loadingLayer && <div className="absolute top-4 right-4 bg-white/90 px-3 py-2 rounded-lg shadow-sm text-xs font-medium flex items-center gap-2 z-10"><RefreshCw className="animate-spin text-emerald-600" size={14} />Processing...</div>}
                {isOffline && <div className="absolute inset-0 bg-white/50 flex items-center justify-center backdrop-blur-[1px] z-10"><div className="bg-white p-4 rounded-xl shadow-lg border border-gray-200 text-center max-w-xs"><Zap size={24} className="mx-auto text-amber-500 mb-2" /><p className="text-sm font-bold text-gray-900">Offline Mode</p></div></div>}
            </div>
        </div>
    );
};

export const FieldDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { parcels, updateParcel } = useParcels();
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [soil, setSoil] = useState<SoilData | null>(null);
  const [loadingSoil, setLoadingSoil] = useState(true);
  const [loading, setLoading] = useState(true);
  const [ndviHistory, setNdviHistory] = useState<NdviPoint[]>([]);
  const [loadingStats, setLoadingStats] = useState(false);
  const [dataSource, setDataSource] = useState<'gee' | 'saved' | null>(null);
  const [backendError, setBackendError] = useState<string | null>(null);

  const isOffline = localStorage.getItem('gee_simulation_mode') === 'true';
  const parcel = parcels.find(p => p.id === id);

  const fetchAndSaveStats = async (currentParcel: Parcel) => {
      if (!currentParcel.boundary) return;
      setLoadingStats(true);
      setBackendError(null);
      try {
          const backendUrl = getBackendUrl();
          const startDate = new Date(currentParcel.date || Date.now());
          startDate.setDate(startDate.getDate() - 10);
          const realData = await fetchGeeTimeSeries(currentParcel.boundary, startDate.toISOString().split('T')[0], new Date().toISOString().split('T')[0], backendUrl);
          if (realData && realData.length > 0) {
              setNdviHistory(realData);
              setDataSource('gee');
              setLoadingStats(false);
              updateParcel(currentParcel.id, { ndviHistory: realData, lastAgroSync: Date.now() }).catch(() => {});
          } else {
              if (currentParcel.ndviHistory) { setNdviHistory(currentParcel.ndviHistory); setDataSource('saved'); }
              setLoadingStats(false);
          }
      } catch(e: any) {
          setBackendError(e.message);
          if (currentParcel.ndviHistory) { setNdviHistory(currentParcel.ndviHistory); setDataSource('saved'); }
          setLoadingStats(false);
      }
  };

  useEffect(() => {
    if (!parcel) return;
    const { lat, lng } = getCoordinates(parcel.location);
    fetchFieldWeather(lat, lng).then(setWeather).finally(() => setLoading(false));

    setLoadingSoil(true);
    fetchSoilData(lat, lng, parcel.boundary).then(setSoil).finally(() => setLoadingSoil(false));

    if (parcel.ndviHistory && parcel.ndviHistory.length > 0 && !isOffline) {
        setNdviHistory(parcel.ndviHistory);
        setDataSource('saved');
        if (!parcel.lastAgroSync || Date.now() - parcel.lastAgroSync > 86400000) fetchAndSaveStats(parcel);
    } else { fetchAndSaveStats(parcel); }
  }, [parcel?.id]);

  if (!parcel) return <div>Not Found</div>;

  const currentNdvi = ndviHistory.length > 0 ? ndviHistory[ndviHistory.length - 1].value : 0;

  return (
    <div className="space-y-6 pb-12">
      <div className="flex items-center gap-4">
        <button onClick={() => navigate('/dashboard')} className="p-2 bg-white border border-gray-200 rounded-lg"><ArrowLeft size={20} /></button>
        <div><h1 className="text-2xl font-bold text-gray-900">{parcel.name}</h1><p className="text-sm text-gray-500">{parcel.location}</p></div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="space-y-6">
            <FieldMonitorMap parcel={parcel} isOffline={isOffline} />
            <div className="bg-white rounded-xl border border-gray-200 p-6">
                <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2"><Sprout className="text-emerald-600" size={20}/> Crop Status</h3>
                <div className="space-y-4">
                    <div className="flex justify-between border-b pb-2"><span>Crop</span><span className="font-bold">{parcel.crop}</span></div>
                    <div className="flex justify-between"><span>NDVI</span><span className="font-bold">{currentNdvi?.toFixed(2) || 'N/A'}</span></div>
                </div>
            </div>
        </div>

        <div className="lg:col-span-2 space-y-6">
            <div className="bg-white rounded-xl border border-gray-200 p-6">
                <h2 className="text-lg font-bold mb-6 flex items-center gap-2"><Activity className="text-emerald-600" size={20} /> Vegetation Index Trend</h2>
                <div className="h-64">
                    <ResponsiveContainer width="100%" height="100%">
                        <LineChart data={ndviHistory}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="date" /><YAxis domain={[0, 1]} /><Tooltip /><Line type="monotone" dataKey="value" stroke="#10b981" strokeWidth={3} dot /></LineChart>
                    </ResponsiveContainer>
                </div>
            </div>

            <div className="bg-white rounded-xl border border-gray-200 p-6">
                <h2 className="text-lg font-bold mb-6 flex items-center gap-2"><Pickaxe className="text-emerald-700" size={20} /> Spatially Averaged Soil Properties</h2>
                {loadingSoil ? <div className="h-40 flex items-center justify-center"><Loader2 className="animate-spin" /></div> : soil ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="bg-gray-50 p-5 rounded-xl border">
                            <h3 className="text-xl font-bold">{soil.texture.label}</h3>
                            <div className="mt-4 space-y-2">
                                <div className="flex justify-between text-sm"><span>Sand</span><span>{soil.texture.sand}%</span></div>
                                <div className="flex justify-between text-sm"><span>Silt</span><span>{soil.texture.silt}%</span></div>
                                <div className="flex justify-between text-sm"><span>Clay</span><span>{soil.texture.clay}%</span></div>
                            </div>
