// ----------------------------------------------------------------------
// SOIL ANALYSIS ENDPOINT (Spatially Averaged via SoilGrids)
// ----------------------------------------------------------------------
app.post('/api/get-soil', async (req, res) => {
  try {
    const { polygon } = req.body;
    if (!polygon) return res.status(400).json({ error: 'polygon required' });
    validatePolygon(polygon);

    const cacheKey = `soil:v1:${Buffer.from(JSON.stringify(polygon)).toString('base64')}`;
    const cached = await cacheGet(cacheKey);
    if (cached) return res.json(cached);

    const region = ee.Geometry(polygon);

    // Aggregate top 30cm (0-5, 5-15, and 15-30cm bands)
    const depths = ['0-5cm', '5-15cm', '15-30cm'];
    const getLayerMean = (assetId, bandPrefix) => {
      const img = ee.Image(assetId);
      const bands = depths.map(d => `${bandPrefix}_${d}_mean`);
      return img.select(bands).reduce(ee.Reducer.mean());
    };

    const topsoil = ee.Image.cat([
      getLayerMean('projects/soilgrids-isric/clay_mean', 'clay').rename('clay'),
      getLayerMean('projects/soilgrids-isric/sand_mean', 'sand').rename('sand'),
      getLayerMean('projects/soilgrids-isric/silt_mean', 'silt').rename('silt'),
      getLayerMean('projects/soilgrids-isric/phh2o_mean', 'phh2o').rename('ph'),
      getLayerMean('projects/soilgrids-isric/soc_mean', 'soc').rename('soc'),
      getLayerMean('projects/soilgrids-isric/bdod_mean', 'bdod').rename('bd')
    ]);

    const stats = topsoil.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 250, // native SoilGrids resolution
      maxPixels: 1e9,
      bestEffort: true
    });

    stats.evaluate(async (data, err) => {
      if (err) return res.status(500).json({ error: err });

      const result = {
        texture: {
          clay: data.clay ? Number((data.clay / 10).toFixed(1)) : null,
          sand: data.sand ? Number((data.sand / 10).toFixed(1)) : null,
          silt: data.silt ? Number((data.silt / 10).toFixed(1)) : null,
        },
        chemistry: {
          ph: data.ph ? Number((data.ph / 10).toFixed(1)) : null,
        },
        organic: {
          soc: data.soc ? Number((data.soc / 100).toFixed(2)) : null,
          som: data.soc ? Number((data.soc / 100 * 1.72).toFixed(2)) : null
        },
        physical: {
          bulkDensity: data.bd ? Number((data.bd / 100).toFixed(2)) : null
        }
      };

      await cacheSet(cacheKey, result, 86400); // Cache for 24 hours as soil data is static
      res.json(result);
    });

  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/get-layer', async (req, res) => {
  try {
    const { polygon, layer = 'ndvi' } = req.body;
    if (!polygon) return res.status(400).json({ error: 'polygon required' });
    validatePolygon(polygon);

    const cacheKey = `map:v11:${layer}:${Buffer.from(JSON.stringify(polygon)).toString('base64')}`;
    const cached = await cacheGet(cacheKey);
    if (cached) {
        console.log(`Returning cached tile URL for ${layer}`);
        return res.json({ tile_url: cached });
    }

    const region = ee.Geometry(polygon);
    const end = ee.Date(Date.now());
    const start = end.advance(-90, 'day');

    let mapImage = null;
    let palette = [];

    const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(start, end)
        .map((img) => img.divide(10000).addBands(
            img.normalizedDifference(['B8', 'B4']).rename('NDVI')
        )); 

    const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterBounds(region)
        .filterDate(start, end)
        .sort('CLOUD_COVER')
        .first()
        .clip(region);

    switch (layer) {
        case 'ndvi':
            mapImage = s2.qualityMosaic('NDVI').clip(region).select('NDVI');
            palette = ['#a1662f', '#eab308', '#84cc16', '#22c55e', '#14532d'];
            break;
        case 'ndre':
            mapImage = s2.qualityMosaic('NDVI').clip(region).normalizedDifference(['B8', 'B5']).rename('NDRE');
            palette = ['#a1662f', '#f59e0b', '#facc15', '#4ade80', '#15803d'];
            break;
        case 'ndmi':
            mapImage = s2.qualityMosaic('NDVI').clip(region).normalizedDifference(['B8', 'B11']).rename('NDMI');
            palette = ['#caf0f8', '#90e0ef', '#00b4d8', '#0077b6', '#03045e'];
            break;
        case 'lai':
            const ndvi = s2.qualityMosaic('NDVI').clip(region).select('NDVI');
            mapImage = ndvi.multiply(2.33).exp().multiply(0.57).rename('LAI');
            palette = ['#f7fcf5', '#caeac3', '#7bc77c', '#2a924a', '#00441b'];
            break;
        case 'lst':
            const kelvin = l9.select('ST_B10').multiply(0.00341802).add(149.0);
            mapImage = kelvin.subtract(273.15).rename('LST');
            palette = ['blue', 'yellow', 'red'];
            break;
        default:
            mapImage = s2.qualityMosaic('NDVI').clip(region).select('NDVI');
            palette = ['#a1662f', '#eab308', '#84cc16', '#22c55e', '#14532d'];
    }

    const stats = mapImage.reduceRegion({
        reducer: ee.Reducer.percentile([2, 98]),
        geometry: region,
        scale: 10,
        maxPixels: 1e9,
        bestEffort: true
    });

    const bandName = mapImage.bandNames().get(0);
    const p2 = stats.get(ee.String(bandName).cat('_p2'));
    const p98 = stats.get(ee.String(bandName).cat('_p98'));

    const visualized = mapImage.visualize({
        min: p2,
        max: p98,
        palette: palette
    });

    const mapid = await getMapIdAsync(visualized, {});
    let tileUrl = mapid.urlFormat || (mapid.tile_fetcher && mapid.tile_fetcher.url_format);

    if (!tileUrl) throw new Error('Could not generate tile URL from Earth Engine response');

    await cacheSet(cacheKey, tileUrl, 60);
    return res.json({ tile_url: tileUrl });
  } catch (err) {
    return res.status(500).json({ error: err.message || String(err) });
  }
});

app.post('/api/get-stats', async (req, res) => {
  try {
    const { polygon, months = 6, startDate, endDate } = req.body;
    if (!polygon) return res.status(400).json({ error: 'polygon required' });
    validatePolygon(polygon);
    const job = await ndviQueue.add({ polygon, months, startDate, endDate }, { removeOnComplete: false, removeOnFail: false });
    return res.json({ jobId: job.id });
  } catch (err) {
    return res.status(500).json({ error: err.message || String(err) });
  }
});

app.get('/api/job/:id', async (req, res) => {
  try {
    const job = await ndviQueue.getJob(req.params.id);
    if (!job) return res.status(404).json({ error: 'job not found' });
    const state = await job.getState();
    const result = await job.returnvalue;
    return res.json({ id: job.id, state, result });
  } catch (err) {
    return res.status(500).json({ error: err.message || String(err) });
  }
});

